	if n, err := strconv.Atoi(os.Getenv("LLM_ATTN_GATHER_HROWS_MIN")); err == nil && n >= 0 {
		return n
	}
	return g.selWidth()
}''')
rep("	attnHeadRowsDefault = false","	attnHeadRowsDefault = true")
open(p,'w').write(s)
