	"math/rand"
	"os"
	"sort"
	"time"

	"strix-halo-vulkan/llm"
)

func med(d []time.Duration) time.Duration {
	sort.Slice(d, func(i, j int) bool { return d[i] < d[j] })
	return d[len(d)/2]
}

func main() {
	m, err := llm.Open(os.Args[1])
	if err != nil {
		panic(err)
	}
	cfg, ok, err := m.PLEConfig()
	if err != nil || !ok {
		panic(fmt.Sprint(ok, err))
	}
	rng := rand.New(rand.NewSource(int64(len(os.Args))+time.Now().UnixNano()))
	ids := make([]int32, 0, 4096)
	for i := 0; i < 64; i++ {
		ids = append(ids, int32(rng.Intn(150000)))
	}
	var te, tr, tg []time.Duration
	for step := 0; step < 200; step++ {
		id := int32(rng.Intn(150000))
		t0 := time.Now()
		if _, err := m.Embeddings([]int32{id}); err != nil {
			panic(err)
		}
		t1 := time.Now()
		ids = append(ids, id)
		rows := llm.PLERowsFrom(cfg, ids, len(ids)-1)
		t2 := time.Now()
		if _, err := m.PLEGather(rows, cfg.NHeads, cfg.HeadDim); err != nil {
			panic(err)
		}
		t3 := time.Now()
		te = append(te, t1.Sub(t0))
		tr = append(tr, t2.Sub(t1))
		tg = append(tg, t3.Sub(t2))
	}
	fmt.Printf("median per decode step: embeddings %v, PLERowsFrom %v, PLEGather %v\n", med(te), med(tr), med(tg))
	// Again over the same ids: now warm.
	var tw []time.Duration
	for i := 64; i < len(ids); i++ {
		rows := llm.PLERowsFrom(cfg, ids[:i+1], i)
		t0 := time.Now()
		m.PLEGather(rows, cfg.NHeads, cfg.HeadDim)
		tw = append(tw, time.Since(t0))
	}
	fmt.Printf("median PLEGather, pages already faulted: %v\n", med(tw))
}
